// TrustLoop wallet upgrade installer.
// Run from the project root:  node apply-wallet.mjs
// Backs up every file it replaces into .backup-wallet/ first.
import fs from "node:fs";
import path from "node:path";

const FILES = {"scripts/backfill-ledger.mjs":"","src/app/actions/auth.ts":"","src/app/actions/mock.ts":"","src/app/actions/payments.ts":"","src/app/actions/wallet.ts":"","src/app/actions/withdraw.ts":"","src/app/actions/work.ts":"","src/app/mock-roqqu/[reference]/page.tsx":"","src/app/wallet/page.tsx":"","src/components/AddMoneyForm.tsx":"","src/components/CopyButton.tsx":"","src/lib/money.ts":"","src/lib/payments/handlers.ts":"","src/lib/payments/index.ts":"","src/lib/payments/mock.ts":"","src/lib/payments/roqqu.ts":"","src/lib/payments/types.ts":"","src/lib/wallet.ts":""};

const MODELS = `
enum LedgerType {
  DEPOSIT
  TASK_FUND
  TASK_PAYOUT
  WITHDRAWAL
  REFUND
}

enum DepositStatus {
  PENDING
  CONFIRMED
  FAILED
}

model LedgerEntry {
  id        String     @id @default(cuid())
  user      User       @relation(fields: [userId], references: [id])
  userId    String
  type      LedgerType
  amountNgn Int
  reference String     @unique
  taskId    String?
  note      String?
  createdAt DateTime   @default(now())

  @@index([userId, createdAt])
}

model Deposit {
  id        String        @id @default(cuid())
  user      User          @relation(fields: [userId], references: [id])
  userId    String
  amountNgn Int
  status    DepositStatus @default(PENDING)
  reference String        @unique
  createdAt DateTime      @default(now())

  @@index([userId])
}
`;

const root = process.cwd();
const schemaPath = path.join(root, "prisma", "schema.prisma");
if (!fs.existsSync(schemaPath) || !fs.existsSync(path.join(root, "src"))) {
  console.error("Run this from the project root (the folder with prisma/ and src/).");
  process.exit(1);
}

// 1. Database schema
let s = fs.readFileSync(schemaPath, "utf8");
if (s.includes("model LedgerEntry")) {
  console.log("schema.prisma already has the wallet models, skipping.");
} else {
  const nl = s.includes("\r\n") ? "\r\n" : "\n";
  const re = /(\n[ \t]*images[ \t]+UserImage\[\][ \t]*\r?\n)(\})/;
  if (!re.test(s)) {
    console.error("Could not find the User model's 'images UserImage[]' line in schema.prisma. Nothing was changed.");
    process.exit(1);
  }
  fs.mkdirSync(path.join(root, ".backup-wallet", "prisma"), { recursive: true });
  fs.writeFileSync(path.join(root, ".backup-wallet", "prisma", "schema.prisma"), s);
  const add = [
    "  depositAddress String?",
    "  depositNetwork String?",
    "  depositSandbox Boolean @default(false)",
    "  ledger         LedgerEntry[]",
    "  deposits       Deposit[]",
  ].join(nl) + nl;
  s = s.replace(re, (_m, a, b) => a + add + b);
  s = s.trimEnd() + nl + MODELS.replace(/\n/g, nl);
  fs.writeFileSync(schemaPath, s);
  console.log("Updated prisma/schema.prisma");
}

// 2. Source files
for (const [rel, b64] of Object.entries(FILES)) {
  const dest = path.join(root, rel);
  if (fs.existsSync(dest)) {
    const bk = path.join(root, ".backup-wallet", rel);
    fs.mkdirSync(path.dirname(bk), { recursive: true });
    fs.copyFileSync(dest, bk);
  }
  fs.mkdirSync(path.dirname(dest), { recursive: true });
  fs.writeFileSync(dest, Buffer.from(b64, "base64"));
  console.log("Wrote " + rel);
}

// 3. Keep the backups out of git
const gi = path.join(root, ".gitignore");
if (fs.existsSync(gi) && !fs.readFileSync(gi, "utf8").includes(".backup-wallet")) {
  fs.appendFileSync(gi, "\n.backup-wallet/\n");
}

console.log(`
Done. Next, run these one at a time:
  1.  npx prisma migrate dev --name wallet
  2.  node scripts/backfill-ledger.mjs
  3.  npm run build
`);
